module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] s [0:20];
  integer i, j, t;
  reg [7:0] tmp;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) s[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      s[0] <= x;
      for (i = 1; i < 21; i = i + 1) s[i] <= s[i-1];
      for (i = 0; i < 20; i = i + 1)
        for (j = i + 1; j < 21; j = j + 1)
          if (s[i] > s[j]) begin tmp <= s[i]; s[i] = s[j]; s[j] = tmp; end
      y <= {8'd0, s[10]};
    end
  end
endmodule

